  'swarm.brood.desc': 'Ein lebendes Brutorgan der Brut-Mutter. Bringt alle 3 Spielstunden einen Landungsträger für 20 Biomasse, 8 Metall und 2 Mikroelektronik hervor. Das Wachstum stoppt im Kampf, bei Rohstoffmangel oder vollem Laderaum.',
