  'data.swarm-instinct': 'Schwarminstinkt',
  'swarm.intel.economy': 'Der Schwarm verschlingt organische Materie für lebendes Gewebe, Metall für Panzerung und Streben sowie Mikroelektronik für leitende neuronale Knoten. Industriewelten treiben seine Ausbreitung an: Biomasse allein reicht nicht aus.',
  'swarm.intel.brood': 'Eine Brut-Mutter trägt eine Brutkammer, ein Organ, das Boden-Landungsträger aus Biomasse, Metall und Mikroelektronik heranzieht. Sie belegen Landungskapazitäten und nehmen die Oberfläche durch einen regulären Sturm ein. Die bloße Anwesenheit infiziert die Welt nicht.',
