  'pve.pirates.title': 'Erste Schlacht · Piraten',
  'pve.pirates.approach': 'Eine nahe Piratenbasis beherbergt zwei Fregatten. Wählen Sie Ihre Startflotte, drücken Sie „Kurs“ und wählen Sie die Basis. Ihre Streitkräfte reichen für den ersten Kampf aus. Dieses Ziel ist optional: Schwarmwellen rücken weiter vor.',
  'pve.pirates.travel': 'Die Flotte fliegt zur Basis. Beim Kontakt mit den Piraten beginnt der Kampf automatisch. Warten Sie auf die Ankunft; die Spielgeschwindigkeit lässt sich unten steuern.',
  'pve.pirates.battle': 'Die Schlacht hat begonnen. Öffnen Sie das Kampffenster: Dort finden Sie Truppenstärken, Rumpfzustand und den Countdown zur nächsten Runde. Schaden wird rundenweise abgerechnet. Ein Rückzug wird über das Flottenpanel befohlen.',
  'pve.pirates.occupy': 'Die Piratenflotte ist vernichtet, doch die Basis gehört noch ihnen. Die Startflotte hat Landungstruppen: Gehen Sie in einen nahen Orbit und befehlen Sie „Sturm“, um die leere Basis zu besetzen.',
  'pve.pirates.won': 'Basis erobert, erster Kampf beendet. Prüfen Sie Flottenverluste und bereiten Sie die Verteidigung gegen den Schwarm vor. Der Sieg in der Expedition steht noch bevor.',
  'pve.pirates.cleared': 'Piratenziel bereits gesichert. Setzen Sie die Vorbereitung auf die Schwarmwellen fort.',
  'pve.pirates.recover': 'Derzeit verfügen Sie über keine Kampfflotte. Bauen Sie neue Einheiten auf der Heimatwerft oder verschieben Sie die Piraten auf später. Die Expedition läuft weiter.',
  'pve.pirates.show': 'Basis anzeigen',
  'pve.pirates.open-battle': 'Schlacht öffnen',
  'run.abandon.lost.title': 'Flotte verloren',
  'run.abandon.lost.text': 'Keine Schiffe mehr übrig. Bauen Sie auf der Werft neu oder beenden Sie die Expedition: Belohnung für Wellen, Aufgaben und zerstörte Feinde — wie bei einer Niederlage.',
  'run.abandon.ask.title': 'Expedition beenden?',
  'run.abandon.ask.text': 'Die Expedition endet sofort mit einer Niederlage. Belohnung: für Wellen, Aufgaben und zerstörte Feinde.',
  'run.abandon.rebuild': 'Neu aufbauen',
  'run.abandon.back': 'Fortsetzen',
  'run.abandon.go': 'Expedition beenden',
  'run.exit.title': 'Expedition verlassen?',
  'run.exit.text': 'Zum Menü — die Expedition wird gespeichert und an derselben Stelle fortgesetzt. Beenden — Niederlage; Belohnung für Wellen, Aufgaben und zerstörte Feinde.',
  'run.exit.double': 'Auf dem Ergebnisbildschirm kann die Belohnung für einen Werbespot verdoppelt werden.',
  'run.exit.reward': 'Jetzt abholen: +{n} Daten, +{w} ⌖',
