  'codex.tag.mechanic': 'Mechanik',
  'codex.tag.module': 'Modul',
  'codex.tag.ship': 'Schiff',
  'codex.term.async.body': 'Die Welt läuft in Echtzeit und bleibt rund um die Uhr aktiv — auch nachdem Sie das Spiel verlassen. Befehle dauern reale Stunden: Kurs setzen, Spiel schließen und später zum Ergebnis zurückkehren.',
  'codex.term.async.title': 'Asynchrone Welt',
  'codex.term.attack.body': 'Salvenstärke beim Angriff dieser Flotte. Wird sie angegriffen, antwortet sie mit [[defense|Verteidigung]]. Nur die [[fire-line|Feuerlinie]] schießt in einer Salve.',
  'codex.term.attack.title': 'Angriff',
  'codex.term.capture.body': 'Die Eroberung einer Welt verläuft in zwei Phasen. Zuerst die Umlaufbahn betreten und Verteidiger im Raum besiegen; hält die Welt eine Garnison, landen Sie Bodentruppen (eine Division aus dem Laderaum).',
  'codex.term.capture.title': 'Orbit und Landung',
  'codex.term.coalition.body': 'Diplomatie erlaubt Pakte und Allianzen, doch eine Koalition ist durch kombinierte Stärke begrenzt — man kann sich nicht beliebig gegen einen Spieler verbünden. Das Limit wahrt das Machtgleichgewicht.',
  'codex.term.coalition.title': 'Koalitionsgrenze',
  'codex.term.defense.body': 'Rückfeuerstärke bei gegnerischem Angriff auf die Flotte. Mindert erlittenen Schaden nicht: [[shield|Schild]] und [[hull|Rumpf]] fangen ihn ab.',
  'codex.term.defense.title': 'Verteidigung',
  'codex.term.fire-line.body': 'Nur die {n} stärksten {n|Einheit feuert|Einheiten feuern} in einer Salve. Die restlichen nehmen lediglich Schaden.',
  'codex.term.fire-line.title': 'Feuerlinie',
  'codex.term.fog.body': 'Sie sehen nur, was sich nahe Ihren Kräften und Radaren befindet; der Rest liegt im Nebel oder zeigt alte Erinnerungen. Aufklärer und Radar erweitern die Sicht.',
  'codex.term.fog.title': 'Kriegsnebel',
  'codex.term.hull.body': 'Aktuelle und volle Stärke der Flotte. Repariert über einer eigenen Welt mit Werft oder sofort gegen Credits.',
  'codex.term.hull.title': 'Rumpf',
  'codex.term.lanes.body': 'Flotten reisen nicht in geraden Linien, sondern entlang Sternenrouten zwischen Welten — die Route wird automatisch berechnet. Routenknoten können abgefangen werden: Begegnungen unterwegs führen zur Schlacht.',
  'codex.term.lanes.title': 'Sternenrouten',
  'codex.term.score.body': 'Punkte entstehen aus Besitztümern: eine Welt — 50, jeder andere Sektor — 10, Gebäude addieren pro Stufe. Schlacht um eine Spielerwelt: Sieg +40, Niederlage −5% der Wertung. Erreichen Sie den Schwellenwert zum Sieg. Weitere Pfade: Eliminierung oder Vorherrschaft.',
  'codex.term.score.title': 'Siegpunkte',
  'codex.term.shield.body': 'Nimmt Schaden vor dem [[hull|Rumpf]] und lädt sich außerhalb des Kampfes kostenlos wieder auf.',
  'codex.term.shield.title': 'Schild',
  'codex.term.speed.body': 'Die Flotte bewegt sich mit der Geschwindigkeit ihres langsamsten Schiffes. Ein Schiff mit einem [[hull|Rumpf]] unter 30% fliegt langsamer.',
  'codex.term.speed.title': 'Geschwindigkeit',
  'codex.term.upkeep.body': 'Flotten und Gebäude kosten täglichen Unterhalt. Mineneinkommen abzüglich Unterhalt = Ihr Nettosaldo; bei negativem Saldo leert sich die Kasse.',
  'codex.term.upkeep.title': 'Unterhalt',
