  'dossier.unit.bomber.name': 'Angriffs-Shuttle',
  'dossier.unit.heavy-striker.desc': 'Schweres Anti-Schiff-Shuttle: {a} Schaden gegen Schiffe, {s} pro Stunde gegen Gebäude, {hp} Rumpf, Reichweite {r} bis in die nächste Provinz. Laderaumplätze: {cs}. Freigeschaltet durch Angriffsvektoren.',
  'dossier.unit.heavy-striker.name': 'Schweres Angriffs-Shuttle',
