  'hero.passive.scavenged-guns.desc': '+5% Schaden für das Schiff des Helden.',
  'hero.passive.swarm-instinct.desc': 'Schwarmflotten innerhalb von 42 Einheiten um den Leviathan fliegen 10% schneller.',
  'hero.passive.wreck-optics.desc': '+3% Bergungsanteil in Schlachten dieses Helden.',
  'data.field-lab': 'Feldlabor',
  'data.ballistic-model': 'Ballistisches Modell',
  'hero.passive.ballistic-model.desc': 'Im Modulplatz: +10% Schaden für die Flotte des Helden.',
  'hero.passive.field-lab.desc': '+10% Bergungsanteil in Schlachten dieses Helden.',
  'hero.tree.field-foundry.desc': 'Erbeutetes Metall wird im Laderaum eingeschmolzen und den Läufen zugeführt: weitere +2% Schaden für das Heldenscliff.',
  'hero.tree.hull-shears.desc': 'Kraftbetriebene Scheren öffnen Panzerung schneller als sie abkühlt: weitere +2% Bergungsanteil.',
  'hero.tree.salvage-rig.desc': 'Greifer und Schneider auf externen Halterungen: +3% Bergungsanteil in Schlachten des Helden.',
