  'hero.tree.scavenger-mastery.desc': 'Gipfel der Handwerkskunst: weitere +5% Bergungsanteil und +3% Schaden.',
  'hero.person.commander.name': 'Mark Weir',
  'hero.person.commander.bio': 'Ein Veteran der Tiefraum-Feldzüge. Als er umzingelt war, führte er versprengte Schiffe durch Fintenmanöver und brachte ihre Besatzungen nach Hause. Ein Neural-Interface hilft ihm, die Schlacht im Blick zu behalten, doch er überlässt Entscheidungen über Leben niemals Maschinen. Zurückhaltend und fordernd hält er stets eine Reserve für den Rückzug bereit.',
  'hero.person.ravager.name': 'Lyra Sain',
  'hero.person.ravager.bio': 'Sie überlebte die Zerstörung der Forschungsstation, auf der ihre psionische Gabe erwachte. Seitdem erforscht sie die Grenzen ihres Einflusses auf den Raum. Ruhig und entschlossen verlangt sie sich eisiserne Disziplin ab. Für sie ist Macht nur gerechtfertigt, wenn ein Schlag eine Schlacht beendet, statt sie zu verlängern.',
  'hero.person.vanguard.name': 'Darian Cross',
  'hero.person.vanguard.bio': 'Er begann als Geleitschutz-Kommandant auf gefährlichen Handelsrouten. Nach schwerer Verwundung kehrte er mit Kommunikations- und Taktikimplantaten auf die Brücke zurück. Er erkundet ungewisse Routen zuerst und führt Verstärkungen persönlich an. Direkt und schnell bei Entscheidungen schätzt er Eigeninitiative seiner Crew.',
  'hero.person.warden.name': 'Elena Mor',
  'hero.person.warden.bio': 'Jahrelang begleitete sie Evakuierungskonvois am Rande des besiedelten Raums. Ihre psionische Disziplin entwickelte sie, um Menschen zu beschützen, nicht um über ihnen zu stehen. Ruhig unter Beschuss kennt sie den Preis jedes Befehls. Ihr Schiff verlässt den Schauplatz zuletzt, sobald alle anderen in Sicherheit sind.',
  'hero.person.scientist.bio': 'Schöpfer des Programms, aus dem der Schwarm hervorging. Er wurde in den ersten Stunden der Quarantäne aus dem Komplex evakuiert — verletzt, aber arbeitsfähig. Das Kommando misstraut ihm, hat ihn jedoch beauftragt, den Schwarm aufzuhalten: Nur er versteht die Grundprinzipien des Systems. Für ihn ist das kein Befehl, sondern eine Schuld gegenüber jenen, die nicht gerettet werden konnten.',
  'hero.person.main.bio': 'Sie befehligen dieses Flaggschiff. Sein Rufzeichen folgt Ihrem Namen im Match. Ihre Geschichte wird von Ihren Entscheidungen geprägt: wen Sie schützen, wo Sie Risiken eingehen und wann Sie sich zurückziehen. Diese Karte zeigt Ihre Fähigkeiten, Talente und Schiffsausrüstung.',
  'hero.person.dossier': 'Personalakte',
  'hero.person.archetype': 'Spezialisierung',
  'hero.person.grade': 'Seltenheit',
  'hero.person.ships': 'Schiffe in Flotte',
  'hero.person.reserve': 'Flaggschiff in Reserve',
  'hero.person.ship-stats': 'Flaggschiff-Werte mit installierten Modulen',
  'hero.ability.annihilate.desc': 'Verwandelt einen Planeten im Umkreis von 500 in eine tote Welt.',
  'hero.ability.annihilate.name': 'Vernichten',
  'hero.ability.boarding-translocation.desc': 'Passiv. Der Held rückt als separate Flotte neben einer beliebigen Ihrer Flotten aus. Eine Flotte im Transit kann nicht als Landepunkt dienen.',
  'hero.ability.bulwark.desc': 'Temporärer Schild: +15% Verteidigung für eigene Flotten im Umkreis von 42 um den Helden für 2 Stunden. Das Kommandogitter erweitert den Radius auf 220, dann auf 334.',
  'hero.ability.bulwark.name': 'Bollwerk',
  'hero.ability.corridor.desc': 'Ein Korridor zu einer Welt im Umkreis von 300: +50% Geschwindigkeit für die Flotten des Helden. Nur die Armee des Helden darf ihn nutzen, und er schließt sich bei Ankunft. Ausbauten halten ihn 6 Stunden offen und machen ihn für alle zugänglich, auch für Feinde.',
  'hero.ability.corridor.name': 'Korridor',
  'hero.ability.decoy-signal.desc': 'Täuscht einen Radarkontakt vor: Ein Knoten im Umkreis von 400 erscheint 4 Stunden lang mit Signatur 8 auf feindlichem Radar als besetzt. Löst sich auf, sobald der Gegner nahe herankommt.',
  'hero.ability.diplomatic-landing.desc': 'Passiv. Alliierte Welten empfangen den Helden wie ihren eigenen: Das Schiff des Helden kann von einem alliierten Planeten starten.',
  'hero.ability.hive-call.desc': '+15% Schaden für Schwarmflotten im Umkreis von 220 um den Leviathan für 2 Stunden.',
  'hero.ability.devour.desc': 'Eine Welt unter dem Bombardement des Leviathans wird nach 4 Stunden zu einer toten Welt. Ein Kampf mit ihrer Flotte oder das Verlassen des Orbits bricht die Belagerung ab.',
  'hero.ability.rally.desc': 'Ein Kampfruf: +10% Schaden für Ihre Flotten im Umkreis von 42 um den Helden für 2 Stunden. Das Kommandogitter erweitert den Radius auf 220, dann auf 334.',
  'hero.ability.rally.name': 'Sammeln',
  'hero.ability.recall.desc': 'Ruft das Schiff des Helden sofort zur Hauptstadt zurück.',
  'hero.ability.recall.name': 'Rückruf',
  'hero.ability.scan.desc': 'Lüftet 3 Stunden lang den Nebel im Umkreis von 250 um ein Ziel bis zu 400 Entfernung. Ausbauten erhöhen den Schaden an Feinden in der Zone um +5% und senken den an eigenen Flotten um −5%.',
  'hero.ability.scan.name': 'Scan',
  'hero.ability.warp-jump.desc': 'Ein Raumsprung: Das Heldenscliff und seine Truppen springen sofort zu einem Knoten im Umkreis von 350, auch durch den Nebel hindurch. Nicht verfügbar, solange das Schiff im Kampf ist.',
  'hero.arch.commander': 'Kommandant',
  'hero.arch.destroyer': 'Zerstörer',
  'hero.arch.vanguard': 'Vorhut',
