  'hero.grade.main': 'Haupt',
  'hero.grade.rare': 'Selten',
  'hero.hook.combat-damage': 'Schaden an nahen Flotten',
  'hero.hook.fleet-speed': 'Flottengeschwindigkeit',
  'hero.passive.convoy-impulse.desc': 'Flotten, die eine Route von einem Knoten im Umkreis von 42 um den Helden beginnen, fliegen diese 8% schneller.',
  'hero.passive.rally-beacon.desc': '+8% Schaden für Ihre Flotten im Umkreis von 42 um den Helden.',
  'hero.passive.asteroid-pilot.desc': '+20% Geschwindigkeit für das Schiff des Helden in Asteroidenfeldern.',
  'hero.passive.vanguard-impulse.desc': '+10% Geschwindigkeit für die Flotte des Helden.',
  'hero.tree.corridor-open.desc': 'Öffnet den Korridor für alle, auch für Feinde. Verbündete nutzen ihn mit +50% Geschwindigkeit.',
  'hero.tree.corridor-sustained.desc': 'Der Korridor bleibt nach Durchzug der Heldenarmee offen und hält 6 Stunden ab Eröffnung.',
  'hero.tree.command-relay.desc': 'Das Relais leitet Befehle zum nächsten Knoten: Der Radius von Sammeln und Bollwerk wächst von 42 auf 220.',
  'hero.tree.command-grid.desc': 'Das Gitter deckt benachbarte Knoten vollständig ab: Der Radius von Sammeln und Bollwerk wächst von 220 auf 334.',
  'hero.tree.false-echo.desc': 'Schaltet die Fähigkeit Ködersignal frei.',
  'hero.tree.fleet-uplink.desc': 'Die neurale Verbindung erfasst den gesamten Befehl: Flotten, die eine Route von einem Knoten im Umkreis von 42 um den Helden starten, fliegen diese 8% schneller.',
  'hero.tree.asteroid-navigation.desc': 'Wegfindung durch Trümmer: +20% Geschwindigkeit für das Schiff des Helden in Asteroidenfeldern.',
  'hero.tree.neural-lace.desc': 'Ein Gehirn-Steuerkonsole-Implantat: +10% Geschwindigkeit für die Flotte des Helden.',
  'hero.tree.overclocked-helm.desc': 'Das Übertakten des neuralen Interfaces schaltet die Fähigkeit Korridor für den Helden frei.',
  'hero.tree.psi-evasion.desc': 'Eigene und verbündete Flotten in der Scan-Zone erleiden 5% weniger Schaden.',
  'hero.tree.psi-veil.desc': 'Geschärfte Psi-Sicht: Schaltet die Fähigkeit Scan frei.',
  'hero.tree.psi-weak-points.desc': 'Das Radar erkennt Schwachstellen feindlicher Panzerung: Feindflotten in der Scan-Zone erleiden 5% mehr Schaden.',
  'hero.tree.void-attunement.desc': 'Die Psi-Resonanz des Helden inspiriert nahe Flotten: +8% Schaden für Ihre Flotten im Umkreis von 42.',
  'hero.tree.void-translocator.desc': 'Ein Korridorfehler schleuderte einst ein Schiff weit am Ausgang vorbei, und es kehrte intakt zurück. Nun wird dieser Fehler gezielt genutzt: Schaltet die Fähigkeit Warpsprung frei.',
  'hero.unit.commander.desc': 'Der Flaggschiff-Held: Ein Befehls-Transhumaner, der die Flotte stärkt und Korridore öffnet.',
  'hero.unit.leviathan.desc': 'Boss des Veteranen-Schwarms: Ein lebendes Flaggschiff mit 900 Rumpf und 240 Chitin, das zwischen Schlachten nachwächst. Erscheint mit der letzten Welle; sein Tod ist endgültig.',
  'hero.unit.ravager.desc': 'Ein psionischer Zerstörer: Vernichtet Welten und reißt den Nebel auf.',
  'hero.unit.scientist.desc': 'Ein Analyst: Hebt den Nebel durch Aufklärung auf. Angeboren — Feldlabor: +10% Bergungsanteil in Schlachten des Helden.',
  'hero.unit.vanguard.desc': 'Ein transhumaner Manövrist: Korridore und ein Schlachtruf für führende Flotten.',
  'hero.unit.warden.desc': 'Ein psionischer Verteidiger: Hält die Linie hinter einem Bastionsschild.',
