  'onb.guide.welcome': 'Lernen ohne Gegner: Wirtschaft, Flotte, Markt, Held, Truppen, Luftfahrt und Sturm.',
  'onb.guide.nav': 'Probieren Sie die Kartengesten aus. Drücken Sie danach „Weiter“.',
  'onb.guide.home': 'Wählen Sie Ihre hervorgehobene Heimatwelt. „Anzeigen“ richtet die Kamera auf sie aus.',
  'onb.guide.details': 'Öffnen Sie „Details“, um die Gebäude der Welt zu sehen.',
  'onb.guide.mine': 'Öffnen Sie die Karte der Metallmine — sie liefert Metall für Schiffe.',
  'onb.guide.mine-order': 'Drücken Sie „Ausbauen“. Die Kosten werden einmalig abgebucht; der Ausbau benötigt Spielzeit.',
  'onb.guide.mine-close': 'Ausbau in Auftrag gegeben. Schließen Sie die Karte — der Bau läuft weiter.',
  'onb.guide.mine-wait': 'Warten Sie auf Stufe 2 der Mine. Die Lernzeit ist 300-fach beschleunigt.',
  'onb.guide.tech': 'Öffnen Sie nun die Wissenschaft: Ein neues Schiff muss zuerst erforscht werden.',
  'onb.guide.research-tab': 'Wählen Sie den Zweig „Raumfahrt“: Hier befindet sich der Fregatten-Bauplan.',
  'onb.guide.research': 'Drücken Sie bei der Fregatte auf „Erforschen“. Aufklärer erobern keine Gebiete.',
  'onb.guide.research-wait': 'Forschung läuft. Warten Sie auf die Freischaltung der Fregatte — danach bauen wir sie.',
  'onb.guide.research-close': 'Fregatte freigeschaltet. Schließen Sie das Forschungsfenster und kehren Sie zur Heimatwelt zurück.',
  'onb.guide.ships-tab': 'Öffnen Sie den Reiter „Flotte“ der Heimatwelt — hier werden Schiffe bestellt.',
  'onb.guide.ship': 'Öffnen Sie die Karte der Fregatte. Dieses Schiff kann unbesetzte Gebiete einnehmen.',
  'onb.guide.ship-order': 'Drücken Sie „Hier bauen“, um eine Fregatte zu bestellen.',
  'onb.guide.ship-wait': 'Die Fregatte wird gebaut. Nach Fertigstellung geht sie automatisch in den Orbit der Heimatwelt.',
  'onb.guide.fleet': 'Wählen Sie die hervorgehobene Flotte mit der Fregatte. Der anfängliche Späher eignet sich nicht zur Eroberung.',
  'onb.guide.move': 'Drücken Sie „Bewegen“, um das Ziel der Route festzulegen.',
  'onb.guide.course': 'Klicken Sie auf den hervorgehobenen Asteroidensektor ohne Garnison.',
  'onb.guide.course-confirm': 'Ziel ausgewählt. Drücken Sie „Entsenden“, um die Route zu bestätigen.',
  'onb.guide.capture': 'Die Flotte ist unterwegs. Der freie Sektor gehört Ihnen, sobald die Fregatte eintrifft.',
  'onb.guide.score': 'Sektor erobert! Gebiete bringen Punkte ein. Eine Welt mit Garnison erfordert Truppen und einen Sturm.',
  'onb.guide.done': 'Kurs abgeschlossen. Starten Sie ein Solo-Match im Hub. Tutorial wiederholen: „Mehr“ → „Tutorial“.',
  'onb.tour.got-it': 'Verstanden',
  'onb.tour.hud.clock': 'Die Welt läuft in Echtzeit weiter, sogar offline. Hier befinden sich Pause und Beschleunigung.',
  'onb.tour.hud.done': 'Bauen Sie die Metallmine aus, erstellen Sie eine Flotte und setzen Sie einen Kurs.',
  'onb.tour.hud.purse': 'Schatzkammer: Einnahmen aus dem Bergbau minus Flottenunterhalt.',
  'onb.tour.hud.tools': 'Fenster des Kommandanten: Diplomatie, Wissenschaft, Produktion, Markt und Ereignisse.',
  'onb.tour.hud.welcome': 'Kurze Führung durch die Benutzeroberfläche. „Tutorial überspringen“ ist bei jedem Schritt verfügbar.',
