  'sector-zero.mission.3.brief': 'Drei Übergänge durch die Quarantänelinie. Halten Sie diese, ohne die Reserven aufzubrauchen.',
  'sector-zero.mission.4': 'IV · Das schweigende Archiv',
  'sector-zero.mission.4.brief': 'Treffen Sie die verbündete Abteilung, bergen Sie das Datenpaket aus dem Archiv und eskortieren Sie den Träger ins Lager. Der Verlust des Trägers führt zur Niederlage.',
  'sector-zero.mission.5': 'V · Zerrissenes Netz',
  'sector-zero.mission.5.brief': 'Nehmen und halten Sie die drei Schwarm-Herde gemeinsam mit der verbündeten Abteilung. Das Zerschlagen des Netzwerks verwehrt ihnen gemeinsame Erfahrung, ist aber nicht zwingend erforderlich.',
