  'sector-zero.mission.6.brief': 'Gemeinsam mit dem Verbündeten: Zerschlagen Sie drei Produktionsherde des Schwarms, vernichten Sie seine drei Hauptstreitkräfte und evakuieren Sie die Menschen aus den Quarantänedocks — bringen Sie 3 von 4 Transportern zur Basis. Weniger bedeutet Niederlage.',
