  'steward.on.active.note': 'Während Sie schlafen: Hält Grenzen und Shuttle-Patrouillen über Ihren Welten und greift bei eigenen Welten an, wenn die Verlustprognose akzeptabel ist.',
  'steward.on.defense': 'Der Verwalter hält die Linie.',
