  'steward.ready': 'Der Verwalter ist bereit.',
  'steward.ready.note': 'Übergeben Sie Ihren Platz einer vertrauenswürdigen KI, während Sie offline sind — sie hält die Stellung und gibt das Kommando rechtzeitig zurück.',
