  'steward.stance.active': 'Aktive Verteidigung',
  'steward.stance.active.note': 'Aktive Verteidigung: Alles oben Genannte, plus Gegenangriffe bei eigenen Welten bei vertretbarer Verlustprognose (unter 35%) und Shuttle-Patrouillen. Verlässt niemals das eigene Territorium.',
  'steward.stance.defense': 'Verteidigung',
