  'tech.node.ace-programs.desc': 'Fliegerass-Programme: Elitebesatzungen. +6% Shuttle-Schaden, +6% Flottengeschwindigkeit. Der krönende Abschluss des Geschwader-Kommodores.',
  'tech.node.ai-stewardship.desc': 'Befehlsautomatisierung: Übergeben Sie Ihr Kommando an eine vertrauenswürdige KI, während Sie offline (im Schlaf) sind — sie hält die Stellung und übergibt die Kontrolle pünktlich zurück. Äußerst mächtig, erfordert den Aufseher-Wissenschaftler und öffnet sich erst ab Tag 16.',
  'tech.node.combined-arms.desc': 'Verbundene Waffen: Infanterie und Panzer im Gleichschritt. +5% Bodenkampfschaden.',
  'tech.node.deep-survey.desc': 'Tiefensensoren-Netzwerke: +15% Radarreichweite.',
  'tech.node.flight-decks.desc': 'Flugdecks: Schnellerer Einsatzzyklus. +6% Flottengeschwindigkeit.',
  'tech.node.fortified-infrastructure.desc': 'Doktrin befestigter Welten — Grenzfestungen.',
  'tech.node.garrison-networks.desc': 'Garnisonsnetzwerke: Das Hinterland versorgt sich selbst. +5% Produktion.',
  'tech.node.guidance-arrays.desc': 'Zielerfassungs-Arrays: Weitreichende Telemetrie. +10% Radarreichweite.',
  'tech.node.industrial-automation.desc': 'Planetare Logistik-Aufwertung: +10% Produktion.',
  'tech.node.logistics-command.desc': 'Logistikkommando: Konvois nach Fahrplan. +5% Produktion und Flottengeschwindigkeit.',
  'tech.node.microelectronics-fabrication.desc': 'Orbitale Gießereien: +5% Produktion.',
  'tech.node.void-shipworks.desc': 'Liegedecks, Treibstoffzisternen und Reparaturgerüste, die direkt in die Festung integriert sind. Schaltet einen eigenen Hangar frei — Shuttles benötigen keinen Bodenraumhafen mehr.',
  'tech.node.void-shielding.desc': 'Feldemitter entlang des Festungsrumpfs: Eine Salve wird vom Schutzfeld abgeschwächt, bevor sie die Panzerung trifft. Schaltet das Schild-Array frei — drei Stufen, jeweils breiter und schneller wiederaufgeladen.',
  'tech.node.void-fortification.desc': 'Ein Stützpunkt außerhalb planetarer Systeme: Tragender Rahmen, Reaktorgürtel und Anlegeplätze verwandeln leeren Raum in einen entwickelbaren Posten. Schaltet die Leerenfestung frei.',
  'tech.node.orbital-defense-grid.desc': 'Orbitales Verteidigungsgitter: Schaltet die orbitale Flugabwehrstellung frei — eine Batterie, die Schiffe im Orbit beschießt.',
  'tech.node.orbital-logistics.desc': 'Standardisierter Gütertransport: +12% Flottengeschwindigkeit.',
  'tech.node.planetary-bastions.desc': 'Planetare Bastionen: Eine Vollzyklus-Rüstungsindustrie. +8% Bodenkampfschaden. Der krönende Abschluss des Marschalls.',
  'tech.node.saturation-barrage.desc': 'Sättigungssperrfeuer: Überwältigt jede Raketenabwehr. +10% Raketenschaden. Der krönende Abschluss des Raketenchefs.',
  'tech.node.siege-doctrine.desc': 'Weitreichende Belagerungsmannschaften: +8% Schaden im Weltraum.',
  'tech.node.signal-corps.desc': 'Signaltruppen: Ein einheitliches Lagebild der Schlacht. +8% Radarreichweite.',
  'tech.node.strike-vectors.desc': 'Angriffsvektoren: Berechnete Shuttle-Anflugkurse. +8% Shuttle-Schaden.',
  'tech.node.void-armadas.desc': 'Großverbands-Doktrin: +6% Schaden im Raum, +6% Flottengeschwindigkeit. Erfordert 5 eigene Sektoren.',
  'tech.node.warhead-miniaturization.desc': 'Sprengkopf-Miniaturisierung: Dichte Salven pro Tonne. +6% Raketenschaden.',
